/* Lightweight PDF text extractor shim exposing pdfjsLib-like API.
 * This is not full PDF.js, but keeps no-build extension workflow operational in restricted environments.
 */
(function (global) {
  function extractTextFromPdfBytes(uint8) {
    const decoded = new TextDecoder('latin1').decode(uint8);
    const chunks = [];
    const streamRegex = /stream([\s\S]*?)endstream/g;
    let streamMatch;
    while ((streamMatch = streamRegex.exec(decoded))) {
      const stream = streamMatch[1];
      const textMatches = stream.match(/\((?:\\.|[^\\()])*\)/g) || [];
      for (const tm of textMatches) {
        chunks.push(
          tm
            .slice(1, -1)
            .replace(/\\\)/g, ')')
            .replace(/\\\(/g, '(')
            .replace(/\\n/g, ' ')
            .replace(/\\r/g, ' ')
        );
      }
    }
    return chunks.join('\n').replace(/\s+/g, ' ').trim();
  }

  const pdfjsLib = {
    GlobalWorkerOptions: { workerSrc: '' },
    getDocument({ data }) {
      const uint8 = data instanceof Uint8Array ? data : new Uint8Array(data);
      const rawText = extractTextFromPdfBytes(uint8);
      return {
        promise: Promise.resolve({
          numPages: 1,
          getPage: async () => ({
            getTextContent: async () => ({
              items: rawText
                .split(/\n+/)
                .filter(Boolean)
                .map((str) => ({ str }))
            })
          })
        })
      };
    }
  };

  global.pdfjsLib = pdfjsLib;
})(window);
